import React from 'react'
import { styleOf } from '@/lib/qpu-style'
export const QpuBadge: React.FC<{ uuid: string; label?: string }> = ({ uuid, label }) => (
  <span style={{ ...styleOf(uuid), background: 'var(--qpu-accent)', color: 'white', borderRadius: 'var(--qpu-radius)', padding: '0 var(--qpu-gap)', fontFamily: 'monospace' }} title={uuid}>{label ?? uuid.slice(0, 8)}</span>
)
